"""Textos de la página «UML Ajedrez»: relaciones, clases, flechas que no hay y preguntas.

Las referencias se arman con ln(archivo, texto) para que nunca queden números de línea a mano.
"""
from base import lineas, RUTA


def ln(archivo, texto, k=1):
    vistas = [i for i, l in enumerate(lineas(archivo), 1) if texto in l]
    if len(vistas) < k:
        raise SystemExit(f"No encontré «{texto}» en {archivo}")
    return f"{archivo}:{vistas[k - 1]}"


